INSERT INTO public.artworks (title, medium, dimensions, year, description, image_path, alt_text, sort_order, published) VALUES
('Morning, Kitchen North', 'Oil on linen', '80 × 100 cm', '2024', 'A first light study made over three mornings, chasing the moment the north window turns the wall to ochre.', 'seed/art-morning-kitchen.jpg', 'Warm abstract gesture painting with ochre and soft red washes on textured canvas', 1, true),
('Field at Noon', 'Acrylic on panel', '60 × 75 cm', '2024', 'Painted from memory after a walk outside Porto, when the heat flattened every colour into gold.', 'seed/art-field-noon.jpg', 'Soft warm landscape painting of sunlit fields in muted gold and terracotta', 2, true),
('Figure, Unnamed', 'Gouache & pastel', '50 × 50 cm', '2024', 'A single sitting, worked quickly. The figure stays unnamed so the gesture can speak first.', 'seed/art-figure.jpg', 'Expressive figure study in warm clay tones with gestural brushwork', 3, true),
('Window 04', 'Oil on canvas', '100 × 140 cm', '2024', 'The fourth in an ongoing series about one tall window and the way it holds the afternoon.', 'seed/art-window.jpg', 'Abstract interior painting with a single tall window of pale light and warm shadows', 4, true),
('Still, Two Pears', 'Oil on linen', '45 × 55 cm', '2024', 'A quiet still life built in thin layers of honey and rust, finished when the cloth felt warm.', 'seed/art-pears.jpg', 'Warm still life painting of two pears and folded cloth in honey and rust tones', 5, true),
('Dusk, Studio Door', 'Mixed media on board', '70 × 88 cm', '2024', 'Made at the end of the day in dusty rose and cream, with impasto scraped back and rebuilt.', 'seed/art-dusk.jpg', 'Layered abstract painting in dusty rose and cream with textured impasto', 6, true);